import urllib.request,concurrent.futures,json
from pathlib import Path
p=Path(__file__).parent;out=p/'public/assets/free';out.mkdir(exist_ok=True)
photos=[(17840537,'wooden-chair-in-a-minimalist-living-room','Bilal Mansuri'),(8123029,'wooden-chair-inside-an-empty-apartment','Faruk Tokluoglu'),(10780943,'wooden-chair-in-an-empty-room-in-sunlight','Yusuf P'),(3952048,'minimalist-interior-style-with-wooden-table-and-chairs-at-home','Ksenia Chernaya'),(17919765,'chair-and-table-in-a-room','Feyza Yildirim'),(6436757,'kitchen-and-living-room-interiors-at-home','Max Vakhtbovych'),(6890399,'comfortable-sofa-placed-near-wooden-counter-and-kitchen-in-apartment','Max Vakhtbovych'),(37070073,'modern-minimalist-living-room-interior-design','UMUT'),(26571206,'interior-design-of-living-room-and-kitchen','Pexels contributor'),(29120629,'modern-minimalist-open-concept-living-space','Pexels contributor'),(10486238,'living-room-with-beige-sofa-and-wooden-table','Pexels contributor'),(33827324,'modern-office-interior-with-natural-light','Capture Crew'),(36847580,'modern-sunlit-office-space-with-desk-and-chairs','Salim Da'),(36777590,'modern-home-office-interior-with-natural-light','Curtis Adams'),(40574006,'elegant-architectural-arches-in-soft-light','Sami Raad'),(35374088,'sunlight-through-arched-door-in-minimalist-architecture','Saad Bin Hasan'),(4916281,'modern-staircase-in-house-under-sunlight','Maria Orlova'),(30609234,'minimalist-office-design-with-natural-light','Jomin Thach'),(36287488,'modern-office-interior-in-milano-with-green-plants','Earth Photart'),(29672793,'sunlit-interior-with-shadows-and-arches','Abdullah Oguk'),(7534232,'modern-design-for-the-office-interior','Max Vakhtbovych'),(36167549,'elegant-black-and-white-portrait-of-woman','Pexels contributor'),(29407201,'classic-black-and-white-portrait-of-woman','Pexels contributor'),(19039585,'woman-portrait-in-black-and-white','Pexels contributor'),(16478898,'woman-portrait-in-black-and-white','Pexels contributor'),(20022690,'portrait-of-man-in-black-and-white','Jonathan Borba'),(23228228,'portrait-of-man-in-black-and-white','Jean Marc Bonnel')]
def download(row):
 id,slug,author=row;dest=out/f'pexels-{id}.jpg';url=f'https://images.pexels.com/photos/{id}/pexels-photo-{id}.jpeg?auto=compress&cs=tinysrgb&w=2400'
 try:
  if not dest.exists(): dest.write_bytes(urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0','Referer':'https://www.pexels.com/'}),timeout=40).read())
  return {'id':id,'file':f'/assets/free/pexels-{id}.jpg','source':f'https://www.pexels.com/photo/{slug}-{id}/','photographer':author,'license':'https://www.pexels.com/license/'}
 except Exception as e: print('FAILED',id,str(e));return None
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:rows=[r for r in pool.map(download,photos) if r]
(p/'src/free-photos.json').write_text(json.dumps(rows,indent=2),encoding='utf8');print('Downloaded',len(rows),'free photos')

